/* ============================================
   PUBLICATIONS READING EXPERIENCE

   Three-layer progressive disclosure:
   - Overview (H1) - Main reading column
   - Analysis (H2) - Panel from right
   - In Depth (H3) - Stacked panel from right
   ============================================ */

const TRANSITION_DURATION = 450;

// State management
let publicationData = null;
let currentChapter = null;
let currentSection = null;
let currentSubsection = null;
let currentLayer = 'overview';

// DOM Elements (initialized on DOMContentLoaded)
let readingColumn, readingContent;
let analysisPanel, analysisPanelTitle, analysisPanelContent;
let indepthPanel, indepthPanelTitle, indepthPanelContent;
let layerName, layerBoxes, tocList, tocSidebar, layerIndicatorEl;

// ============================================
// INITIALIZATION
// ============================================

document.addEventListener('DOMContentLoaded', async () => {
    // Cache DOM elements
    readingColumn = document.getElementById('readingColumn');
    readingContent = document.getElementById('readingContent');
    analysisPanel = document.getElementById('analysisPanel');
    analysisPanelTitle = document.getElementById('analysisPanelTitle');
    analysisPanelContent = document.getElementById('analysisPanelContent');
    indepthPanel = document.getElementById('indepthPanel');
    indepthPanelTitle = document.getElementById('indepthPanelTitle');
    indepthPanelContent = document.getElementById('indepthPanelContent');
    layerName = document.getElementById('layerName');
    layerBoxes = document.getElementById('layerBoxes');
    tocList = document.getElementById('tocList');
    tocSidebar = document.getElementById('tocSidebar');
    layerIndicatorEl = document.getElementById('layerIndicator');

    if (document.body.hasAttribute('data-prerendered')) {
        // Static page generated by scripts/generate-publications.js: every layer
        // is already in the DOM for crawlers — hydrate the interactive reader
        // from it instead of fetching/parsing markdown.
        hydrateFromDOM();
    } else {
        // Draft-preview mode: fetch and render the markdown at runtime
        const slug = getSlugFromURL();
        if (!slug) {
            renderError('No publication specified. Add ?pub=filename to the URL.');
            return;
        }
        await loadPublication(slug);
    }

    // Setup interactions
    initSmoothScroll();
    setupPanelCloseButtons();
    setupKeyboardNavigation();
    setupScrollTracking();
    setupTocProximity();
    setupSubscribe();

    // Restore state from URL if applicable
    restoreFromURL();
});

// ============================================
// SMOOTH SCROLL (Lenis) — buttery inertial wheel scroll, progressive enhancement
// ============================================

// Lenis runs in document mode (scrolls the real <html>), so the fixed sidebar,
// panels, layer indicator and subscribe block keep working, and the
// IntersectionObserver chapter-tracker stays accurate. Nested scrollers (the
// sidebar and each panel body) opt out via [data-lenis-prevent] in the markup.
let lenis = null;

function initSmoothScroll() {
    const reduce = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    if (reduce || typeof window.Lenis !== 'function') return; // native scroll remains

    lenis = new window.Lenis({
        duration: 1.1,
        easing: (t) => Math.min(1, 1.001 - Math.pow(2, -10 * t)),
        smoothWheel: true,
        wheelMultiplier: 1,
        touchMultiplier: 1.5
    });

    function raf(time) {
        lenis.raf(time);
        requestAnimationFrame(raf);
    }
    requestAnimationFrame(raf);

    window.__lenis = lenis;
}

// Route programmatic scrolls through Lenis when active, else native smooth scroll.
function smoothScrollTo(target, options = {}) {
    if (lenis) {
        lenis.scrollTo(target, options);
    } else if (typeof target === 'number') {
        window.scrollTo({ top: target, behavior: 'smooth' });
    } else if (target && target.scrollIntoView) {
        target.scrollIntoView({ behavior: 'smooth', block: options.block || 'start' });
    }
}

// ============================================
// HYDRATION (pre-rendered static pages)
// ============================================

// Rebuild publicationData from the pre-rendered DOM. Layer-2/3 content lives in
// each subsection card's hidden .layer-detail block (Layer-3 notes as nested
// .layer-note sections); the panel logic then works exactly as in preview mode.
function hydrateFromDOM() {
    const chapters = [];

    document.querySelectorAll('.chapter-card').forEach(card => {
        const titleEl = card.querySelector('.chapter-title');
        const chapter = {
            id: card.id,
            title: titleEl ? titleEl.textContent.trim() : '',
            content: '',
            sections: []
        };

        card.querySelectorAll('.subsection-card').forEach(subCard => {
            const subTitleEl = subCard.querySelector('.subsection-title');
            const sectionTitle = subTitleEl ? subTitleEl.textContent.trim() : '';
            const subsections = [];
            let sectionContent = '';

            const detail = subCard.querySelector('.layer-detail');
            if (detail) {
                const clone = detail.cloneNode(true);
                clone.querySelectorAll('.layer-note').forEach(note => {
                    const heading = note.querySelector('h4');
                    const noteTitle = note.dataset.noteTitle ||
                        (heading ? heading.textContent.trim() : '');
                    if (heading) heading.remove();
                    subsections.push({
                        id: slugify(noteTitle),
                        title: noteTitle,
                        content: note.innerHTML
                    });
                    note.remove();
                });
                sectionContent = clone.innerHTML;
            }

            chapter.sections.push({
                id: slugify(sectionTitle),
                title: sectionTitle,
                content: sectionContent,
                subsections
            });
        });

        chapters.push(chapter);
    });

    const mastheadTitle = document.querySelector('.masthead-title');
    publicationData = {
        title: mastheadTitle ? mastheadTitle.textContent.trim() : document.title,
        author: document.getElementById('publicationAuthor').textContent.trim(),
        date: document.getElementById('publicationDate').textContent.trim(),
        abstract: '',
        category: '',
        chapters
    };
}

function getSlugFromURL() {
    const params = new URLSearchParams(window.location.search);
    return params.get('pub');
}

// ============================================
// DATA LOADING
// ============================================

async function loadPublication(slug) {
    try {
        // Fetch markdown file
        const response = await fetch(`content/publications/${slug}.md`);
        if (!response.ok) {
            throw new Error(`Publication not found: ${slug}`);
        }
        const markdownText = await response.text();

        // Parse frontmatter and content
        const { metadata, content } = parseFrontmatter(markdownText);

        // Parse markdown into structured chapters
        publicationData = parseMarkdownStructure(content, metadata);

        // Update page title
        document.title = `${publicationData.title} | India AI Tracker`;

        // Render the publication
        renderPublication();

    } catch (error) {
        console.error('Error loading publication:', error);
        renderError(`Failed to load publication: ${error.message}`);
    }
}

// ============================================
// FRONTMATTER PARSING
// ============================================

function parseFrontmatter(text) {
    const frontmatterRegex = /^---\s*\n([\s\S]*?)\n---\s*\n([\s\S]*)$/;
    const match = text.match(frontmatterRegex);

    if (!match) {
        // No frontmatter, treat entire text as content
        return {
            metadata: { title: 'Untitled', author: '', date: '' },
            content: text
        };
    }

    const frontmatterText = match[1];
    const content = match[2];

    // Simple YAML parsing for flat key: value pairs
    const metadata = {};
    frontmatterText.split('\n').forEach(line => {
        const colonIndex = line.indexOf(':');
        // Only treat top-level (unindented) keys as flat fields; nested blocks
        // like takeaways are handled separately by extractTakeaways().
        if (colonIndex > 0 && !/^\s/.test(line)) {
            const key = line.substring(0, colonIndex).trim();
            let value = line.substring(colonIndex + 1).trim();
            if ((value.startsWith('"') && value.endsWith('"')) ||
                (value.startsWith("'") && value.endsWith("'"))) {
                value = value.slice(1, -1);
            }
            metadata[key] = value;
        }
    });

    // Nested "takeaways: { summary, points[] }" block (draft-preview best effort;
    // the static generator parses this with full js-yaml).
    const takeaways = extractTakeaways(frontmatterText);
    if (takeaways) metadata.takeaways = takeaways;

    return { metadata, content };
}

// Line-scan the "takeaways:" mapping for summary (inline or folded) + points list.
function extractTakeaways(frontmatterText) {
    const stripQuotes = (v) => (
        (v.startsWith('"') && v.endsWith('"')) || (v.startsWith("'") && v.endsWith("'"))
            ? v.slice(1, -1)
            : v
    );
    const lines = frontmatterText.split('\n');
    let i = lines.findIndex(l => /^takeaways:\s*$/.test(l));
    if (i === -1) return null;

    const summaryParts = [];
    const points = [];
    let mode = null; // 'summaryFold' | 'points'

    for (i = i + 1; i < lines.length; i++) {
        const line = lines[i];
        if (line.trim() === '') continue;
        if (/^\S/.test(line)) break; // dedented to a new top-level key → block ends

        const summaryInline = line.match(/^\s{2}summary:\s*(.*)$/);
        const pointsKey = /^\s{2}points:\s*$/.test(line);
        const listItem = line.match(/^\s{2,}-\s+(.*)$/);

        if (summaryInline) {
            const v = summaryInline[1].trim();
            if (v === '' || /^[>|]-?$/.test(v)) {
                mode = 'summaryFold';
            } else {
                summaryParts.push(stripQuotes(v));
                mode = null;
            }
        } else if (pointsKey) {
            mode = 'points';
        } else if (listItem && mode === 'points') {
            points.push(stripQuotes(listItem[1].trim()));
        } else if (mode === 'summaryFold') {
            summaryParts.push(line.trim());
        }
    }

    const summary = summaryParts.join(' ').trim();
    if (!summary && points.length === 0) return null;
    return { summary, points };
}

// ============================================
// MARKDOWN STRUCTURE PARSING
// ============================================

function parseMarkdownStructure(markdown, metadata) {
    const chapters = [];
    const lines = markdown.split('\n');

    let currentH1 = null;
    let currentH2 = null;
    let currentH3 = null;
    let contentBuffer = [];

    function flushContent() {
        const html = marked.parse(contentBuffer.join('\n').trim());
        if (currentH3 && currentH2) {
            currentH3.content = html;
        } else if (currentH2 && currentH1) {
            currentH2.content += html;
        } else if (currentH1) {
            currentH1.content += html;
        }
        contentBuffer = [];
    }

    for (const line of lines) {
        if (line.startsWith('# ') && !line.startsWith('## ') && !line.startsWith('### ')) {
            // H1 - New chapter (Overview layer)
            flushContent();
            if (currentH2 && currentH1) {
                currentH1.sections.push(currentH2);
            }
            if (currentH1) {
                chapters.push(currentH1);
            }

            currentH1 = {
                id: slugify(line.substring(2)),
                title: line.substring(2).trim(),
                content: '',
                sections: []
            };
            currentH2 = null;
            currentH3 = null;

        } else if (line.startsWith('## ') && !line.startsWith('### ')) {
            // H2 - New section (Analysis layer)
            flushContent();
            if (currentH2 && currentH1) {
                currentH1.sections.push(currentH2);
            }

            currentH2 = {
                id: slugify(line.substring(3)),
                title: line.substring(3).trim(),
                content: '',
                subsections: []
            };
            currentH3 = null;

        } else if (line.startsWith('### ')) {
            // H3 - New subsection (In Depth layer)
            flushContent();
            if (currentH3 && currentH2) {
                currentH2.subsections.push(currentH3);
            }

            currentH3 = {
                id: slugify(line.substring(4)),
                title: line.substring(4).trim(),
                content: ''
            };

        } else {
            contentBuffer.push(line);
        }
    }

    // Flush remaining content
    flushContent();
    if (currentH3 && currentH2) {
        currentH2.subsections.push(currentH3);
    }
    if (currentH2 && currentH1) {
        currentH1.sections.push(currentH2);
    }
    if (currentH1) {
        chapters.push(currentH1);
    }

    return {
        title: metadata.title || 'Untitled',
        author: metadata.author || '',
        date: metadata.date || '',
        abstract: metadata.abstract || '',
        category: metadata.category || '',
        takeaways: (metadata.takeaways && typeof metadata.takeaways === 'object')
            ? metadata.takeaways
            : null,
        chapters
    };
}

function slugify(text) {
    return text.toLowerCase()
        .replace(/[^a-z0-9\s-]/g, '')
        .replace(/\s+/g, '-')
        .replace(/-+/g, '-')
        .replace(/^-|-$/g, '');
}

// ============================================
// RENDERING
// ============================================

function renderPublication() {
    // Update hero
    document.getElementById('publicationTitle').textContent = publicationData.title;
    document.getElementById('publicationAuthor').textContent = publicationData.author;
    document.getElementById('publicationDate').textContent = formatDate(publicationData.date);

    // Render TOC
    renderTableOfContents();

    // Render Overview layer (main content)
    renderOverviewContent();
}

function formatDate(dateStr) {
    if (!dateStr) return '';
    try {
        const date = new Date(dateStr);
        return date.toLocaleDateString('en-US', { month: 'long', year: 'numeric' });
    } catch {
        return dateStr;
    }
}

function renderTableOfContents() {
    let html = '';

    publicationData.chapters.forEach((chapter, index) => {
        // H2 sub-items, revealed via CSS when this chapter is active
        let subHtml = '';
        if (chapter.sections.length > 0) {
            subHtml = '<ul class="toc-sub">';
            chapter.sections.forEach((section, sectionIndex) => {
                subHtml += `
                    <li><a href="#${chapter.id}"
                           onclick="openAnalysisPanel(${index}, ${sectionIndex}); return false;">
                        ${section.title}
                    </a></li>
                `;
            });
            subHtml += '</ul>';
        }

        html += `
            <li class="toc-item" data-chapter="${index}">
                <span class="toc-marker" aria-hidden="true"></span>
                <div class="toc-item-row">
                    <span class="toc-num">${String(index + 1).padStart(2, '0')}</span>
                    <a href="#${chapter.id}"
                       class="toc-link"
                       data-chapter="${index}"
                       onclick="scrollToChapter('${chapter.id}'); return false;">
                        ${chapter.title}
                    </a>
                </div>
                ${subHtml}
            </li>
        `;
    });

    tocList.innerHTML = html;
}

// Extract the first <p> of a rendered-HTML block, used as the card teaser
function firstParagraphOf(html) {
    const match = html.match(/<p>[\s\S]*?<\/p>/);
    return match ? match[0] : '';
}

// Estimate reading time across every layer's text (words ÷ 220 wpm)
function estimateReadingMinutes() {
    const strip = html => html.replace(/<[^>]+>/g, ' ');
    let words = 0;
    publicationData.chapters.forEach(ch => {
        words += strip(ch.content).split(/\s+/).filter(Boolean).length;
        ch.sections.forEach(s => {
            words += strip(s.content).split(/\s+/).filter(Boolean).length;
            s.subsections.forEach(sub => {
                words += strip(sub.content).split(/\s+/).filter(Boolean).length;
            });
        });
    });
    return Math.max(1, Math.round(words / 220));
}

function buildMastheadHtml() {
    const sep = '<span class="byline-sep">&middot;</span>';
    const bylineParts = [];
    if (publicationData.author) bylineParts.push(`By ${publicationData.author}`);
    if (publicationData.date) bylineParts.push(formatDate(publicationData.date));
    bylineParts.push(`${estimateReadingMinutes()} min read`);

    return `
        <header class="publication-masthead">
            ${publicationData.category ? `<div class="masthead-kicker">${publicationData.category}</div>` : ''}
            <h1 class="masthead-title">${publicationData.title}</h1>
            <div class="masthead-byline">${bylineParts.join(sep)}</div>
            ${publicationData.abstract ? `<p class="masthead-lede">${publicationData.abstract}</p>` : ''}
        </header>
    `;
}

// Escape text then promote **phrase** to a navy UltraBold highlight span.
function renderInlineEmphasis(text) {
    const esc = String(text)
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;');
    return esc.replace(/\*\*([^*]+)\*\*/g, '<span class="hl">$1</span>');
}

function buildTakeawaysHtml() {
    const block = publicationData.takeaways || {};
    const items = (Array.isArray(block.points) ? block.points : [])
        .map(t => String(t).trim())
        .filter(Boolean);
    if (!items.length) return '';

    const summaryText = (block.summary || '').trim();
    const summary = summaryText
        ? `<p class="pub-takeaways-summary">${renderInlineEmphasis(summaryText)}</p>
            <hr class="pub-takeaways-rule">`
        : '';

    return `
        <aside class="pub-takeaways" aria-label="Key takeaways">
            <div class="pub-takeaways-kicker">The short version</div>
            <h2 class="pub-takeaways-title">Key takeaways</h2>
            ${summary}
            <ul class="pub-takeaways-list">
                ${items.map(t => `<li>${renderInlineEmphasis(t)}</li>`).join('')}
            </ul>
        </aside>
    `;
}

// Inline "Weekly Brief" block at the end of the article — the laptop/mobile
// home for the CTA (the fixed right-gutter block only appears ≥1900px). Same
// copy, field, LinkedIn link and Brevo wiring as .pub-sub.
function buildInlineSignupHtml() {
    return `
        <aside class="pub-signup-inline" aria-label="Subscribe to the Weekly Brief">
            <div class="pub-sub-kicker">Weekly Brief</div>
            <h2 class="pub-signup-inline-title">Get our insights delivered to your inbox.</h2>
            <form class="pub-sub-form" novalidate>
                <input type="email" class="pub-sub-input" name="email" placeholder="Your email address"
                       autocomplete="email" required aria-label="Email address">
                <button type="submit" class="pub-sub-btn">Subscribe</button>
            </form>
            <p class="pub-sub-note">Governance analysis, no spam &mdash; unsubscribe anytime.</p>
            <p class="pub-sub-success">Thanks &mdash; you're on the list.</p>
            <a class="pub-sub-linkedin" href="https://www.linkedin.com/company/kanan-labs/"
               target="_blank" rel="noopener">
                <svg width="15" height="15" viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><path d="M20.45 20.45h-3.56v-5.57c0-1.33-.02-3.04-1.85-3.04-1.86 0-2.14 1.45-2.14 2.94v5.67H9.35V9h3.41v1.56h.05c.48-.9 1.63-1.85 3.36-1.85 3.6 0 4.27 2.37 4.27 5.45v6.29zM5.34 7.43a2.06 2.06 0 1 1 0-4.13 2.06 2.06 0 0 1 0 4.13zM7.12 20.45H3.56V9h3.56v11.45zM22.22 0H1.77C.79 0 0 .77 0 1.72v20.56C0 23.23.79 24 1.77 24h20.45c.98 0 1.78-.77 1.78-1.72V1.72C24 .77 23.2 0 22.22 0z"/></svg>
                <span>Follow on LinkedIn</span>
            </a>
        </aside>
    `;
}

function renderOverviewContent() {
    let html = buildMastheadHtml() + buildTakeawaysHtml();

    publicationData.chapters.forEach((chapter, chapterIndex) => {
        const chapterNumber = chapterIndex + 1;
        html += `
            <section class="chapter-card" id="${chapter.id}" data-chapter="${chapterIndex}">
                <div class="chapter-kicker">Chapter ${chapterNumber}</div>
                <h2 class="chapter-title">${chapter.title}</h2>
                <div class="chapter-content">${chapter.content}</div>
        `;

        // One bordered subsection card per H2 (opens the Analysis layer)
        chapter.sections.forEach((section, sectionIndex) => {
            let notesHtml = '';
            if (section.subsections.length > 0) {
                notesHtml = `
                    <div class="subsection-notes">
                        <div class="notes-label">See more about</div>
                        ${section.subsections.map(sub =>
                            `<div class="note-item">&#9776;&nbsp; Note: ${sub.title}</div>`
                        ).join('')}
                    </div>
                `;
            }

            html += `
                <div class="subsection-card"
                     id="card-${chapterIndex}-${sectionIndex}"
                     onclick="openAnalysisPanel(${chapterIndex}, ${sectionIndex})"
                     role="button"
                     tabindex="0">
                    <div class="subsection-id">${chapterNumber}.${sectionIndex + 1}</div>
                    <h3 class="subsection-title">${section.title}</h3>
                    <div class="subsection-teaser">${firstParagraphOf(section.content)}</div>
                    ${notesHtml}
                    <div class="more-strip">Get the details <span class="more-icon">&rarr;</span></div>
                </div>
            `;
        });

        html += '</section>';
    });

    html += buildInlineSignupHtml();

    readingContent.innerHTML = html;
}

// ============================================
// PANEL MANAGEMENT
// ============================================

function openAnalysisPanel(chapterIndex, sectionIndex) {
    const chapter = publicationData.chapters[chapterIndex];
    const section = chapter.sections[sectionIndex];

    currentChapter = chapterIndex;
    currentSection = sectionIndex;
    currentLayer = 'analysis';

    // Update panel content
    analysisPanelTitle.textContent = section.title;

    let panelHtml = section.content;

    // Add subsection links if they exist
    if (section.subsections.length > 0) {
        panelHtml += '<div class="subsection-links">';
        section.subsections.forEach((sub, subIndex) => {
            panelHtml += `
                <a class="subsection-link"
                   onclick="openIndepthPanel(${chapterIndex}, ${sectionIndex}, ${subIndex})"
                   role="button"
                   tabindex="0">
                    <span class="subsection-link-text">${sub.title}</span>
                    <span class="subsection-link-arrow">&rarr;</span>
                </a>
            `;
        });
        panelHtml += '</div>';
    }

    analysisPanelContent.innerHTML = panelHtml;

    // Highlight the trigger card (connector dot + drawn line, stays above the dim)
    clearActiveCards();
    const card = document.getElementById(`card-${chapterIndex}-${sectionIndex}`);
    if (card) {
        card.classList.add('active');
        // Align the card's corner dot with the panel spot on one horizontal line.
        // Preferred: scroll the page so the card's top edge lands at 50vh (the
        // spot's default). Near the document's top/bottom the scroll clamps and
        // can't get there — in that case pin the spot to the card's settled
        // position instead, so the dots stay parallel for every card.
        const cardTop = card.getBoundingClientRect().top;
        const docTarget = window.scrollY + cardTop - window.innerHeight / 2;
        const maxScroll = Math.max(0, document.documentElement.scrollHeight - window.innerHeight);
        const clamped = Math.min(Math.max(0, docTarget), maxScroll);
        // finalCardTop is target-based (absolute card top − target scroll), so the
        // spot lands correctly whether Lenis animates or the scroll clamps.
        const finalCardTop = window.scrollY + cardTop - clamped;
        smoothScrollTo(clamped);

        const spot = analysisPanel.querySelector('.spot');
        if (spot) spot.style.top = `${Math.round(finalCardTop)}px`;
    }

    // Per-layer dim backdrop — clicking it closes this layer (progressive)
    addBackdrop('analysis', closeAnalysisPanel);

    // Animate panel open — overlays the right in place; the article does not move
    requestAnimationFrame(() => {
        analysisPanel.classList.add('open');
        updateLayerIndicator('Analysis');
    });

    // Update URL
    updateURL();
}

function closeAnalysisPanel() {
    // Close in-depth panel first if open
    if (indepthPanel.classList.contains('open')) {
        closeIndepthPanel();
    }

    currentSection = null;
    currentLayer = 'overview';

    removeBackdrop('analysis');
    clearActiveCards();

    requestAnimationFrame(() => {
        analysisPanel.classList.remove('open');
        updateLayerIndicator('Overview');
    });

    // Update URL
    updateURL();
}

function openIndepthPanel(chapterIndex, sectionIndex, subsectionIndex) {
    const chapter = publicationData.chapters[chapterIndex];
    const section = chapter.sections[sectionIndex];
    const subsection = section.subsections[subsectionIndex];

    currentSubsection = subsectionIndex;
    currentLayer = 'indepth';

    // Update panel content
    indepthPanelTitle.textContent = subsection.title;
    indepthPanelContent.innerHTML = subsection.content;

    // Second dim layer over L2; clicking it closes only In-Depth (progressive)
    addBackdrop('indepth', closeIndepthPanel);

    // Keep the L2 → L3 connector on one line: the In-Depth spot mirrors the
    // Analysis spot's height (which may be pinned off-center near document edges)
    const l2Spot = analysisPanel.querySelector('.spot');
    const l3Spot = indepthPanel.querySelector('.spot');
    if (l2Spot && l3Spot) l3Spot.style.top = l2Spot.style.top || '50%';

    // Animate panel open — stacks over Analysis, which shifts left leaving a
    // visible band (its spot shrinks and its connector line draws across)
    requestAnimationFrame(() => {
        indepthPanel.classList.add('open');
        analysisPanel.classList.add('pushed');
        updateLayerIndicator('In Depth');
    });

    // Update URL
    updateURL();
}

function closeIndepthPanel() {
    currentSubsection = null;
    currentLayer = 'analysis';

    removeBackdrop('indepth');

    requestAnimationFrame(() => {
        indepthPanel.classList.remove('open');
        analysisPanel.classList.remove('pushed');
        updateLayerIndicator('Analysis');
    });

    // Update URL
    updateURL();
}

// ============================================
// BACKDROPS & ACTIVE CARDS
// ============================================

function addBackdrop(layer, closeFn) {
    // One backdrop per layer at a time
    if (document.querySelector(`.layer-backdrop.backdrop-${layer}`)) return;

    const backdrop = document.createElement('div');
    backdrop.className = `layer-backdrop backdrop-${layer}`;
    backdrop.addEventListener('click', closeFn);
    document.body.appendChild(backdrop);

    // Fade in on the next frame so the transition runs
    requestAnimationFrame(() => {
        requestAnimationFrame(() => backdrop.classList.add('on'));
    });
}

function removeBackdrop(layer) {
    document.querySelectorAll(`.layer-backdrop.backdrop-${layer}`).forEach(backdrop => {
        backdrop.classList.remove('on');
        setTimeout(() => backdrop.remove(), 350);
    });
}

function clearActiveCards() {
    document.querySelectorAll('.subsection-card.active').forEach(card => {
        card.classList.remove('active');
    });
}

// ============================================
// LAYER INDICATOR
// ============================================

function updateLayerIndicator(layer) {
    if (!layerName || !layerIndicatorEl) return;

    // Display label in uppercase for visual parity
    layerName.textContent = layer.toUpperCase();

    // Update indicator state classes
    layerIndicatorEl.classList.remove('layer-overview', 'layer-analysis', 'layer-indepth');

    let depth = 1;
    if (layer === 'Overview') {
        layerIndicatorEl.classList.add('layer-overview');
        depth = 1;
    } else if (layer === 'Analysis') {
        layerIndicatorEl.classList.add('layer-analysis');
        depth = 2;
    } else if (layer === 'In Depth') {
        layerIndicatorEl.classList.add('layer-indepth');
        depth = 3;
    }

    // Stacked page-boxes: one per open layer, last box carries the orange border
    if (layerBoxes) {
        layerBoxes.innerHTML = Array.from({ length: depth }, (_, k) =>
            `<span class="lbox" style="left: ${(k * 0.45).toFixed(2)}rem"></span>`
        ).join('');
    }
}

// ============================================
// NAVIGATION
// ============================================

function scrollToChapter(chapterId) {
    const element = document.getElementById(chapterId);
    if (element) {
        smoothScrollTo(element, { block: 'start', offset: 0 });
    }
}

function setupPanelCloseButtons() {
    document.getElementById('closeAnalysisBtn').addEventListener('click', closeAnalysisPanel);
    document.getElementById('closeIndepthBtn').addEventListener('click', closeIndepthPanel);
    // Progressive click-outside close is handled by the per-layer backdrops
    // (each backdrop closes only its own layer) — see addBackdrop().
}

// "Weekly Brief" signup. Binds BOTH the right-gutter block (.pub-sub, wide
// screens) and the inline end-of-article fallback (.pub-signup-inline, laptops/
// mobile). Both post to the shared Brevo endpoint via window.brevoSubscribe
// (js/brevo-subscribe.js), matching the site footer form.
function setupSubscribe() {
    document.querySelectorAll('.pub-sub-form').forEach(bindSubscribeForm);
}

function bindSubscribeForm(form) {
    const wrap = form.closest('.pub-sub, .pub-signup-inline');
    const input = form.querySelector('.pub-sub-input');
    const btn = form.querySelector('.pub-sub-btn');

    form.addEventListener('submit', (e) => {
        e.preventDefault();
        const email = input ? input.value.trim() : '';
        if (!email) return;

        if (btn) { btn.disabled = true; btn.textContent = 'Subscribing…'; }
        if (input) input.disabled = true;

        const subscribe = typeof window.brevoSubscribe === 'function'
            ? window.brevoSubscribe(email)
            : Promise.reject(new Error('brevoSubscribe not loaded'));

        subscribe
            .then(() => {
                if (wrap) wrap.classList.add('is-success');
            })
            .catch((err) => {
                console.error('Weekly Brief subscription failed:', err);
                if (btn) { btn.disabled = false; btn.textContent = 'Subscribe'; }
                if (input) input.disabled = false;
                const note = wrap && wrap.querySelector('.pub-sub-note');
                if (note) {
                    note.style.color = '#c23e22';
                    note.textContent = 'Something went wrong. Please try again.';
                }
            });
    });
}

function setupKeyboardNavigation() {
    document.addEventListener('keydown', (e) => {
        if (e.key === 'Escape') {
            if (currentLayer === 'indepth') {
                closeIndepthPanel();
            } else if (currentLayer === 'analysis') {
                closeAnalysisPanel();
            }
        }
    });

    // Allow Enter/Space on subsection cards and More-about links
    document.addEventListener('keydown', (e) => {
        if (e.target.classList.contains('subsection-card') ||
            e.target.classList.contains('subsection-link')) {
            if (e.key === 'Enter' || e.key === ' ') {
                e.preventDefault();
                e.target.click();
            }
        }
    });
}

function setupScrollTracking() {
    const observer = new IntersectionObserver((entries) => {
        entries.forEach(entry => {
            if (entry.isIntersecting && entry.intersectionRatio > 0.3) {
                const chapterId = entry.target.id;
                updateTocHighlight(chapterId);
            }
        });
    }, {
        threshold: [0.3],
        rootMargin: '-100px 0px -50% 0px'
    });

    // Observe after content is rendered
    setTimeout(() => {
        document.querySelectorAll('.chapter-card').forEach(chapter => {
            observer.observe(chapter);
        });
    }, 100);
}

function updateTocHighlight(activeChapterId) {
    tocList.querySelectorAll('.toc-item').forEach(item => {
        const link = item.querySelector('.toc-link');
        const isActive = link && link.getAttribute('href') === `#${activeChapterId}`;
        // Active chapter: bold link + its H2 sub-items revealed (CSS-driven)
        item.classList.toggle('active', isActive);
    });
    // Ease the newly-active item's --effect to 1 (and the rest back down)
    if (tocProximityKick) tocProximityKick();
}

// ============================================
// TOC PROXIMITY (LineSidebar port)
// Vanilla adaptation of reactbits.dev/components/line-sidebar: a single rAF
// loop eases each chapter's --effect toward its target with frame-rate
// independent exponential smoothing; CSS derives color/shift/marker from it.
// ============================================

const TOC_PROXIMITY_RADIUS = 90;   // px from the cursor at which items react
const TOC_SMOOTHING = 100;         // ms time-constant of the ease
const tocFalloffSmooth = (p) => p * p * (3 - 2 * p);

let tocProximityKick = null;

function setupTocProximity() {
    if (!tocList) return;
    // Static .active styling (CSS --effect: 1) covers reduced-motion users
    if (window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches) return;

    const targets = [];
    const current = [];
    let raf = null;
    let last = 0;

    const tocItems = () =>
        Array.from(tocList.querySelectorAll(':scope > .toc-item'));

    function frame(now) {
        const dt = Math.min((now - last) / 1000, 0.05);
        last = now;
        const k = 1 - Math.exp(-dt / (TOC_SMOOTHING / 1000));

        let moving = false;
        tocItems().forEach((el, i) => {
            const target = Math.max(targets[i] || 0, el.classList.contains('active') ? 1 : 0);
            const cur = current[i] || 0;
            const next = cur + (target - cur) * k;
            const settled = Math.abs(target - next) < 0.0015;
            const value = settled ? target : next;
            current[i] = value;
            el.style.setProperty('--effect', value.toFixed(4));
            if (!settled) moving = true;
        });

        raf = moving ? requestAnimationFrame(frame) : null;
    }

    function startLoop() {
        if (raf != null) return;
        last = performance.now();
        raf = requestAnimationFrame(frame);
    }

    tocList.addEventListener('pointermove', (e) => {
        tocItems().forEach((el, i) => {
            const row = el.querySelector('.toc-item-row') || el;
            const rect = row.getBoundingClientRect();
            const distance = Math.abs(e.clientY - (rect.top + rect.height / 2));
            targets[i] = tocFalloffSmooth(Math.max(0, 1 - distance / TOC_PROXIMITY_RADIUS));
        });
        startLoop();
    });

    tocList.addEventListener('pointerleave', () => {
        targets.fill(0);
        startLoop();
    });

    tocProximityKick = startLoop;
    startLoop();
}

// ============================================
// URL STATE MANAGEMENT (Deep Linking)
// ============================================

function updateURL() {
    const params = new URLSearchParams(window.location.search);

    // Keep the pub parameter
    const pub = params.get('pub');
    const newParams = new URLSearchParams();
    if (pub) newParams.set('pub', pub);

    if (currentChapter !== null && currentSection !== null) {
        newParams.set('chapter', currentChapter);
        newParams.set('section', currentSection);
    }
    if (currentSubsection !== null) {
        newParams.set('subsection', currentSubsection);
    }

    const newURL = `${window.location.pathname}?${newParams.toString()}`;
    history.replaceState({}, '', newURL);
}

function restoreFromURL() {
    const params = new URLSearchParams(window.location.search);

    const chapter = params.get('chapter');
    const section = params.get('section');
    const subsection = params.get('subsection');

    if (section !== null && chapter !== null) {
        // Delay to allow content to render
        setTimeout(() => {
            openAnalysisPanel(parseInt(chapter), parseInt(section));

            if (subsection !== null) {
                setTimeout(() => {
                    openIndepthPanel(parseInt(chapter), parseInt(section), parseInt(subsection));
                }, TRANSITION_DURATION + 50);
            }
        }, 100);
    }
}

// ============================================
// ERROR HANDLING
// ============================================

function renderError(message) {
    readingContent.innerHTML = `
        <div class="error-state" style="text-align: center; padding: 4rem 2rem;">
            <p style="font-family: 'Telegraf', sans-serif; color: var(--text-secondary); margin-bottom: 1.5rem;">${message}</p>
            <a href="index.html" style="font-family: 'Telegraf', sans-serif; color: var(--accent-orange); text-decoration: underline;">Return to Tracker</a>
        </div>
    `;
    document.getElementById('publicationTitle').textContent = 'Publication Not Found';
}

// Make functions available globally for onclick handlers
window.openAnalysisPanel = openAnalysisPanel;
window.openIndepthPanel = openIndepthPanel;
window.scrollToChapter = scrollToChapter;
